<?php require_login(['admin','teacher']);$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=$pdo->prepare('INSERT INTO homework(class_id,subject_id,teacher_id,title,description,due_date) VALUES(?,?,?,?,?,?)');$s->execute([(int)$_POST['class_id'],(int)$_POST['subject_id'],user()['teacher_id']?:null,trim($_POST['title']),trim($_POST['description']),($_POST['due_date']?:null)]);flash('success','Homework posted.');redirect('index.php?page=homework');}$classes=$pdo->query('SELECT * FROM classes ORDER BY class_name,section')->fetchAll();$subjects=$pdo->query('SELECT * FROM subjects ORDER BY subject_name')->fetchAll();$rows=$pdo->query('SELECT h.*,c.class_name,c.section,s.subject_name FROM homework h JOIN classes c ON c.id=h.class_id JOIN subjects s ON s.id=h.subject_id ORDER BY h.id DESC LIMIT 100')->fetchAll();?><div class="grid2"><section class="panel"><h2>Post Homework</h2><form class="form-grid" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Class<select name="class_id"><?php foreach($classes as $c):?><option value="<?=$c['id']?>"><?=e($c['class_name'].' - '.$c['section'])?></option><?php endforeach;?></select></label><label>Subject<select name="subject_id"><?php foreach($subjects as $s):?><option value="<?=$s['id']?>"><?=e($s['subject_name'])?></option><?php endforeach;?></select></label><label>Title<input required name="title"></label><label>Due Date<input type="date" name="due_date"></label><label class="wide">Description<textarea name="description" rows="6"></textarea></label><button class="btn primary wide">Post Homework</button></form></section><section class="panel"><h2>Recent Homework</h2><?php foreach($rows as $r):?><article class="notice"><b><?=e($r['title'])?></b><small><?=e($r['class_name'].' '.$r['section'].' · '.$r['subject_name'].' · Due '.($r['due_date']?:'—'))?></small><p><?=nl2br(e($r['description']))?></p></article><?php endforeach;?></section></div>
